{
  "sql": [
    {
      "endpoint": "GET ticket/vip_ticket_list",
      "description": "Enables staff to view and search VIP (high-priority) customer trouble tickets. Users can find tickets by ticket number, person in charge (PSC PIC), customer name, phone number (MSISDN), week, or complaint date range. Supports the main ticket list so teams can identify, assign, and track cases that need elevated attention.",
      "query": "SELECT ctt2, psc_pic, week_no, tt_status, complaint_forward_by, case_type, customer_name, user_details_complaint, faulty_msisdn, root_cause2, complaint_datetime FROM `minds`.`thd_ticket` WHERE ctt2 LIKE :ctt2 ORDER BY CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(ctt2, '/', 2), '/', -1) AS UNSIGNED) DESC, CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(ctt2, '/', 3), '/', -1) AS UNSIGNED) DESC, CAST(SUBSTRING_INDEX(ctt2, '/', -1) AS UNSIGNED) DESC LIMIT :page_size OFFSET :offset"
    },
    {
      "endpoint": "GET ticket/total_ticket",
      "description": "Returns how many VIP trouble tickets match the current search (same filters as the ticket list). Used so the portal can show total result count and total number of pages, helping users understand the size of the result set.",
      "query": "SELECT COUNT(*) AS total_tickets FROM `minds`.`thd_ticket` WHERE ctt2 LIKE :ctt2"
    },
    {
      "endpoint": "GET ticket/download_csv",
      "description": "Lets staff export the current list of VIP trouble tickets to a CSV file using the same search filters as the ticket list. Supports reporting, sharing with other teams, and offline analysis without technical export setup.",
      "query": "SELECT update_l1, ctt2, psc_pic, week_no, tt_status, complaint_forward_by, case_type, customer_name, user_details_complaint, faulty_msisdn, root_cause2, complaint_datetime, phone_brand, phone_model, problem, faulty_location_address, latitude, longitude, escalation_datetime, resolved_datetime, resolved_hour, escalation_hour, site_id, serving_cells, cluster, region, state, finding, avg_cell_availability, packet_loss, prb_utilization, ntt_number, cell_upgrade, nqo_feedback, planner_feedback, rollout_feedback, ims_core_feedback, ps_core_feedback, soc_feedback, celcom_feedback, dnb_feedback, conclusion, recommendation, notes, root_cause1, root_cause2, ctt, month, year, running_number, site_technology, morphology, resolve_hour_kpi, escalation_hour_kpi FROM `minds`.`thd_ticket` WHERE ctt2 LIKE :ctt2 ORDER BY CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(ctt2, '/', 2), '/', -1) AS UNSIGNED) DESC, CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(ctt2, '/', 3), '/', -1) AS UNSIGNED) DESC, CAST(SUBSTRING_INDEX(ctt2, '/', -1) AS UNSIGNED) DESC"
    },
    {
      "endpoint": "GET ticket/get_feedback_history_per_group",
      "description": "Shows the full history of feedback from one support group for a given VIP ticket. Lets staff see how that group\u2019s response and updates evolved over time and review the progression of the group\u2019s involvement in resolving the ticket.",
      "query": "SELECT x.group_id, x.name, x.feedback, x.updated_at FROM ( SELECT f.group_id, f.name, f.feedback, f.updated_at, ROW_NUMBER() OVER ( PARTITION BY f.group_id ORDER BY f.updated_at DESC ) AS rn FROM `minds`.`thd_ticket_feedback` f JOIN `minds`.`thd_ticket` t ON t.id = f.ticket_id WHERE t.ctt2 = :ctt2 AND f.group_id = :group_id ) x ORDER BY x.updated_at DESC;"
    },
    {
      "endpoint": "POST ticket/vip_remark_and_feedback_details",
      "description": "Lets support groups add or update feedback and remarks for a VIP ticket. Groups can record assessments, resolution steps, status updates, and coordination notes so progress and communications are documented on the ticket.",
      "query": "SELECT id FROM `minds`.`thd_ticket` WHERE ctt2 = :ctt2"
    },
    {
      "endpoint": "DELETE ticket/delete_ticket",
      "description": "Allows administrators (Superadmin or Admin only) to remove one or more VIP tickets from the system. Used to clean up duplicate, test, or obsolete tickets while keeping the ticket list accurate.",
      "query": "DELETE FROM `minds`.`thd_ticket` WHERE ctt2 IN ({placeholders})"
    },
    {
      "endpoint": "POST email/send",
      "description": "Sends a re-escalation email to a chosen support group for a VIP ticket so they are notified that the ticket needs their attention. Used when staff need to escalate by email (e.g. when the group is not in the portal) and includes the ticket number and an optional message.",
      "query": "SELECT email FROM `minds`.`groups` WHERE group_ptr_id = :group_id"
    },
    {
      "endpoint": "GET vip_ticket_details/",
      "description": "Shows full details for one VIP ticket so staff can see the customer, complaint, dates, site, status, assigned groups, and feedback. Used when opening a ticket to understand the case and take action.",
      "query": "SELECT avg_cell_availability, case_type, celcom_feedback, cell_upgrade, cluster, complaint_datetime, complaint_forward_by, conclusion, ctt, ctt2, customer_name, dnb_feedback, escalation_datetime, escalation_hour, escalation_hour_kpi, faulty_location_address, faulty_msisdn, finding, id, ims_core_feedback FROM `minds`.`thd_ticket` WHERE ctt2 = :ctt2 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET vip_ticket_filter_values/",
      "description": "Supplies the list of valid options for each ticket filter (e.g. person in charge, problem category, status, technology, cluster). Used to build filter dropdowns so users can narrow the ticket list by the right criteria.",
      "query": "SELECT avg_cell_availability, case_type, celcom_feedback, cell_upgrade, cluster, complaint_datetime, complaint_forward_by, conclusion, ctt, ctt2, customer_name, dnb_feedback, escalation_datetime, escalation_hour, escalation_hour_kpi, faulty_location_address, faulty_msisdn, finding, id, ims_core_feedback FROM `minds`.`thd_ticket` WHERE ctt2 = :ctt2 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET get_latest_feedback_per_group/",
      "description": "Shows the latest feedback from each support group for a VIP ticket so staff can see at a glance which groups have responded and what they last said, without loading full history.",
      "query": "SELECT close_date, created_at, feedback, group_id, id, name, open_date, remark, status, ticket_id, turn, updated_at FROM `minds`.`thd_ticket_feedback` WHERE ticket_id = :ticket_id ORDER BY updated_at DESC LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET display_group_details/",
      "description": "Lists all support groups so users can choose who to escalate a VIP ticket to. Used to populate the group dropdown when escalating and to show group names on tickets.",
      "query": "SELECT email, group_ptr_id FROM `minds`.`groups`"
    },
    {
      "endpoint": "GET pic_names/",
      "description": "Lists the persons in charge (PICs) for a support group so users can assign or escalate a VIP ticket to a specific person, not just the group.",
      "query": "SELECT avg_cell_availability, case_type, celcom_feedback, cell_upgrade, cluster, complaint_datetime, complaint_forward_by, conclusion, ctt, ctt2, customer_name, dnb_feedback, escalation_datetime, escalation_hour, escalation_hour_kpi, faulty_location_address, faulty_msisdn, finding, id, ims_core_feedback FROM `minds`.`thd_ticket` LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "POST vip_ticket_creation/",
      "description": "Creates a new VIP customer trouble ticket so the case can be tracked and assigned. Used when logging a new high-priority complaint with customer, complaint, site, and assignment details.",
      "query": "SELECT avg_cell_availability, case_type, celcom_feedback, cell_upgrade, cluster, complaint_datetime, complaint_forward_by, conclusion, ctt, ctt2, customer_name, dnb_feedback, escalation_datetime, escalation_hour, escalation_hour_kpi, faulty_location_address, faulty_msisdn, finding, id, ims_core_feedback FROM `minds`.`thd_ticket` LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "PATCH vip_ticket_details/",
      "description": "Updates an existing VIP ticket so details (customer, complaint, dates, site, status, assignments) stay correct as the case is worked on.",
      "query": "SELECT avg_cell_availability, case_type, celcom_feedback, cell_upgrade, cluster, complaint_datetime, complaint_forward_by, conclusion, ctt, ctt2, customer_name, dnb_feedback, escalation_datetime, escalation_hour, escalation_hour_kpi, faulty_location_address, faulty_msisdn, finding, id, ims_core_feedback FROM `minds`.`thd_ticket` WHERE ctt2 = :ctt2 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "POST create_vip_ticket_remark/",
      "description": "Escalates a VIP ticket to one or more support groups in one step by creating a remark for each group. Used when several groups need to be involved or when escalating in bulk.",
      "query": "SELECT avg_cell_availability, case_type, celcom_feedback, cell_upgrade, cluster, complaint_datetime, complaint_forward_by, conclusion, ctt, ctt2, customer_name, dnb_feedback, escalation_datetime, escalation_hour, escalation_hour_kpi, faulty_location_address, faulty_msisdn, finding, id, ims_core_feedback FROM `minds`.`thd_ticket` LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET get_latest_remark_per_group/",
      "description": "Shows the latest remark from each support group for a VIP ticket so staff can see which groups have responded and what they last said without loading full remark history.",
      "query": "SELECT close_date, created_at, feedback, group_id, id, name, open_date, remark, status, ticket_id, turn, updated_at FROM `minds`.`thd_ticket_feedback` WHERE ticket_id = :ticket_id ORDER BY updated_at DESC LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET download/",
      "description": "Lets users download a file attached to a VIP ticket so they can open screenshots, logs, or other evidence linked to the case.",
      "query": "SELECT close_date, created_at, feedback, group_id, id, name, open_date, remark, status, ticket_id, turn, updated_at FROM `minds`.`thd_ticket_feedback` WHERE ticket_id = :ticket_id ORDER BY updated_at DESC LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET v1/morphology",
      "description": "Describes the subscriber's radio environment (e.g. urban, suburban) for THD Advisory so staff can interpret coverage and signal in the right context.",
      "query": "SELECT RFP_Morphology, Site_ID FROM `minds`.`site4g` WHERE Site_ID = :site_id"
    },
    {
      "endpoint": "GET v1/usage-ratio",
      "description": "Shows how the subscriber's data usage is split across technologies (e.g. 4G, 5G) in THD Advisory so staff can spot technology-specific issues or preferences.",
      "query": "SELECT RFP_Morphology, Site_ID FROM `minds`.`site4g` WHERE Site_ID = :site_id"
    },
    {
      "endpoint": "GET v1/subs-related",
      "description": "Shows how the subscriber uses the service (usage, speeds, quotas) for THD Advisory so staff can see if issues relate to quota, speed, or usage pattern.",
      "query": "SELECT RFP_Morphology, Site_ID FROM `minds`.`site4g` WHERE Site_ID = :site_id"
    },
    {
      "endpoint": "GET v1/voice-call-related",
      "description": "Provides voice call quality and behavior for a subscriber in THD Advisory so staff can investigate call drops, poor quality, or connectivity issues with data.",
      "query": "SELECT RFP_Morphology, Site_ID FROM `minds`.`site4g` WHERE Site_ID = :site_id"
    },
    {
      "endpoint": "GET v2/network-connection-info",
      "description": "Shows how stable the subscriber's data connection is (disconnects, handovers) for THD Advisory so staff can see if complaints match connection problems.",
      "query": "SELECT RFP_Morphology, Site_ID FROM `minds`.`site4g` WHERE Site_ID = :site_id"
    },
    {
      "endpoint": "GET v2/visited-sites",
      "description": "Lists which cell sites the subscriber connected to on a given date for THD Advisory so staff can see movement and which sites were used when issues occurred.",
      "query": "SELECT RFP_Morphology, Site_ID FROM `minds`.`site4g` WHERE Site_ID = :site_id"
    },
    {
      "endpoint": "GET visited_sites_status/",
      "description": "Part of the THD Advisory API (THD_ADVISORY_API_URL). This endpoint provides operational status information for all sites that served a subscriber during a specified time period, enabling correlation of subscriber experience issues with site-level events. The endpoint requires imsi (subscriber identifier), start_date, and end_date as query parameters. The response includes status information for each visited site, including maintenance status (planned or unplanned maintenance events during the period), NTT (Network Trouble Ticket) information (open trouble tickets affecting the site), congestion status (periods of high load or congestion), and potentially other operational states. This contextual information is critical for understanding whether subscriber-reported issues coincide with known site problems, maintenance activities, or congestion events. The data enables customer service representatives to explain issues to subscribers with specific context (e.g., 'the site serving your area was undergoing maintenance'), helps network engineers correlate subscriber complaints with site-level incidents, supports root cause analysis by identifying external factors affecting service, and provides evidence for service quality explanations. This endpoint is essential for comprehensive THD Advisory analysis, providing operational context that complements performance metrics.",
      "query": "SELECT NE_ID, FAULTY_CATEGORY FROM `minds`.`ntt_lte_filter` WHERE id IN (:latest_ids) AND NTT_STATUS = 'Open'"
    },
    {
      "endpoint": "POST opti/kpi/",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). This endpoint provides aggregated KPI (Key Performance Indicator) data for network performance analysis and reporting. The endpoint accepts a JSON request body containing Vendor (equipment vendor identifier for filtering by vendor), date range parameters (start and end dates), KPI selection (which specific KPIs to retrieve), and related filters (technology, region, site type, etc.). The server processes the request, aggregates KPI data according to the specified grouping criteria (typically by vendor, technology, time period, or region), and returns structured chart data optimized for visualization. The response includes time-series data points, grouped aggregations, statistical summaries, and metadata for rendering charts. This endpoint is the primary data source for Opti reporting module's main KPI dashboard charts, enabling users to visualize network performance trends over time, compare performance across vendors or technologies, identify performance degradation periods, and support data-driven decision making for network optimization. The grouped data structure enables efficient chart rendering and supports drill-down analysis workflows.",
      "query": "SELECT * FROM `minds`.`exclusiontm4gdaysite` WHERE DateID BETWEEN :start_date AND :end_date AND SiteID IN (:coverage_id) LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "POST opti/mutltikpi/",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). This endpoint provides multi-KPI data in an ungrouped format, enabling comparison of multiple KPIs on a single chart or visualization. The endpoint accepts a JSON request body similar to opti/kpi/ containing Vendor, date range, and KPI selection parameters. However, unlike opti/kpi/ which returns grouped/aggregated data, this endpoint returns ungrouped data points that preserve individual KPI values and their relationships. The response structure allows multiple KPIs to be plotted together on the same axes or in coordinated visualizations, enabling correlation analysis, trend comparison, and identification of relationships between different performance indicators. This endpoint is essential for advanced analysis workflows where users need to compare multiple KPIs simultaneously, identify correlations between different metrics, understand how different performance indicators relate to each other, and perform comprehensive performance analysis. The ungrouped format provides flexibility for custom visualizations and enables more sophisticated analytical capabilities compared to single-KPI views.",
      "query": "SELECT * FROM `minds`.`exclusiontm4gdaysite` WHERE DateID BETWEEN :start_date AND :end_date AND SiteID IN (:coverage_id) LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET opti/regionkpi/v3",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). GET variant of region KPI with query string; may include schema or behaviour changes in v3. Used in the Opti reporting module when the UI is configured to use the v3 region KPI endpoint.",
      "query": "SELECT * FROM `minds`.`exclusiontm4gdaysite` WHERE DateID BETWEEN :start_date AND :end_date AND SiteID IN (:coverage_id) LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "POST opti/worstcell/kpi/",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). This endpoint identifies and returns cells or sites with the worst performance metrics based on specified KPI criteria. The endpoint accepts a JSON request body containing KPI (which performance indicator to evaluate), Granularity (cell-level or site-level aggregation), Vendor (equipment vendor filter), date range (start and end dates), Coverage (coverage type or area filter), and Exclusion (criteria for excluding certain cells/sites from analysis). The server analyzes performance data, ranks cells or sites by the selected KPI, applies filters and exclusions, and returns a table of worst-performing entities. Each record includes cell/site identification, KPI values, performance rankings, and related metadata. This endpoint is critical for network optimization workflows, enabling network engineers to identify problematic cells or sites requiring attention, prioritize optimization efforts based on performance impact, track improvement progress over time, and support capacity planning by identifying areas with performance issues. The worst-cell analysis helps focus optimization resources on areas with the greatest impact on network performance and user experience.",
      "query": "SELECT * FROM `minds`.`exclusiontm4gdaysite` WHERE DateID BETWEEN :start_date AND :end_date AND SiteID IN (:coverage_id) LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "POST opti/sitekpi/",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). The portal sends Vendor, date range, site filters, and related parameters in the body. The server returns site-level KPI data in table form. Used in the Opti reporting module to show KPI breakdown by site and to support site-level analysis and filtering.",
      "query": "SELECT * FROM `minds`.`exclusiontm4gdaysite` WHERE DateID BETWEEN :start_date AND :end_date AND SiteID IN (:coverage_id) LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "POST opti/sitekpi/download",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). The portal sends the same parameters as the site KPI table (Vendor, dates, filters) in the body. The server returns a file (e.g. CSV or Excel) with the site KPI data. Used in the Opti reporting module to let users download the current site KPI table.",
      "query": "SELECT * FROM `minds`.`exclusiontm4gdaysite` WHERE DateID BETWEEN :start_date AND :end_date AND SiteID IN (:coverage_id) LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "POST opti/kpisummary/",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). The portal sends Vendor, date range, and related filters in the body. The server returns the RAN KPI summary (high-level KPIs). Used in the Opti reporting module to show the summary view and key RAN metrics (POST variant).",
      "query": "SELECT * FROM `minds`.`dnbweekreport` WHERE RegionID = :region_id AND WeekID = :week_id LIMIT :limit"
    },
    {
      "endpoint": "GET opti/kpisummary/getremark",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). The portal sends Vendor, Region, and WeekID as query parameters. The server returns the stored remarks for the KPI summary for that vendor, region, and week. Used in the Opti reporting module to show and edit remarks on the KPI summary view.",
      "query": "SELECT * FROM `minds`.`dnbweekreport` WHERE RegionID = :region_id AND WeekID = :week_id LIMIT :limit"
    },
    {
      "endpoint": "POST opti/kpisummary/storeRemark/",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). The portal sends in the body the remark data (vendor, region, week, remark text, etc.) for the KPI summary. The server stores the remark. Used in the Opti reporting module when a user saves a remark on the KPI summary.",
      "query": "SELECT * FROM `minds`.`dnbweekreport` WHERE RegionID = :region_id AND WeekID = :week_id LIMIT :limit"
    },
    {
      "endpoint": "GET opti/siteinfo/",
      "description": "Part of the Opti reporting API (LATEST_FILE_URL). The portal sends technology, Exclusion, Start_Date, and End_Date as query parameters. The server returns the list of sites (or site filter options) that match the criteria. Used in the Opti reporting module to populate site and technology filters and to restrict the dataset to the selected technology and exclusion rules.",
      "query": "SELECT RFP_Morphology, Site_ID FROM `minds`.`site4g` WHERE Site_ID = :site_id"
    },
    {
      "endpoint": "GET coverageboxesview/",
      "description": "Part of the map API (MAP_API_URL). This endpoint provides high-level coverage and availability metrics displayed in summary boxes on the main dashboard. The endpoint requires no parameters and returns current coverage box metrics including Webe population coverage (percentage of population covered by Webe network), Webe with MOCN (Multi-Operator Core Network coverage statistics), 4G availability (percentage of time 4G service is available), 5G coverage (geographic or population coverage for 5G network), industry benchmarks (comparative metrics against industry standards or competitors), and site counts broken down by technology (MOCN sites, Unifi Mobile sites, DNB 5G sites). These metrics provide executive-level visibility into network coverage and availability performance, enabling quick assessment of network status, identification of coverage gaps, comparison with industry standards, and tracking of network expansion progress. The data is typically updated regularly and represents current network state. The endpoint is essential for dashboard views that require high-level KPIs without detailed drill-down, supporting executive reporting, status monitoring, and strategic decision-making.",
      "query": "SELECT * FROM `minds`.`coverage_boxes` LIMIT 1"
    },
    {
      "endpoint": "PATCH coverageboxesupdate/{id}/",
      "description": "Part of the map API (MAP_API_URL). The portal sends in the body the updated values for the coverage box (e.g. webe_pop_coverage, availability_4g, coverage_5g, industry metrics, site counts) for the given id. The server updates the record. Used by authorised users on the high-level dashboard to edit and save the displayed coverage box values.",
      "query": "SELECT * FROM `minds`.`coverage_boxes` LIMIT 1"
    },
    {
      "endpoint": "GET totalsitenumber/",
      "description": "Part of the map API (MAP_API_URL). It returns the total site counts: MOCN, 4G, and 5G. Used on the high-level dashboard to show how many sites are in the network by technology.",
      "query": "SELECT (SELECT COUNT(DISTINCT Site_ID) FROM `minds`.`site4g`) AS total_4g, (SELECT COUNT(DISTINCT Site_ID) FROM `minds`.`site5g`) AS total_5g"
    },
    {
      "endpoint": "GET technologycoverageweekvalues/",
      "description": "Part of the Ookla reporting API (OOKLA_API_URL). This endpoint provides a catalog of available time periods for which technology coverage data is available in the Ookla reporting system. The endpoint requires no parameters and returns a list or range of available weeks and years, enabling the frontend to build intelligent date selection controls that only show periods with actual data. The response typically includes week identifiers, year information, potentially date ranges, and metadata about data availability or completeness. This endpoint is essential for Ookla reporting module initialization, as it populates week selector dropdowns or date pickers, ensuring users can only select time periods with available data and preventing unnecessary API calls for non-existent data periods. The catalog helps improve user experience by guiding date selection and avoiding empty result sets. The endpoint may include additional metadata such as data completeness indicators, gaps in data availability, or the most recent available week to help users select appropriate analysis periods.",
      "query": "SELECT * FROM minds.ooklasectordaily WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET technologycoveragebyband/",
      "description": "Part of the Ookla reporting API (OOKLA_API_URL). This endpoint provides detailed technology coverage analysis broken down by frequency bands, enabling understanding of how coverage and performance vary across different spectrum allocations. The endpoint requires week_number and year as query parameters to specify the analysis period. The response includes coverage data organized by band (such as 700MHz, 1800MHz, 2100MHz, 2600MHz, etc.), RSRP (Reference Signal Received Power) categories showing signal strength distributions for each band, total count details (number of samples or measurements per band), and average download speeds per band. Band-level analysis is critical for network planning and optimization, as different frequency bands have different propagation characteristics, coverage capabilities, and capacity characteristics. Lower frequency bands typically provide better coverage and building penetration, while higher frequency bands may offer higher capacity. This endpoint enables network engineers and analysts to understand coverage quality by band, identify bands with coverage gaps or performance issues, assess band utilization, and make informed decisions about spectrum allocation and network optimization. The data is essential for Ookla reporting modules that display coverage and speed analysis by band, supporting network planning and optimization efforts.",
      "query": "SELECT * FROM minds.ooklasectordaily WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET totalcountandaveragedlmbpstable/",
      "description": "Part of the Ookla reporting API (OOKLA_API_URL). This endpoint provides comprehensive week-over-week comparison analysis of sampling counts and average download speeds, enabling tracking of performance trends and changes. The endpoint requires week_number and year as query parameters to specify the current week for comparison. The response includes a detailed table structure showing sampling counts (number of measurements or samples), average download speeds, previous week values for comparison, current week values, and delta calculations (changes from previous week) broken down by frequency band and RSRP (signal strength) categories. This granular breakdown enables identification of performance changes at both the band level and signal quality level, helping understand whether changes affect specific bands or signal conditions. Week-over-week comparison is essential for tracking network improvements, identifying performance degradation, assessing the impact of optimization efforts, and monitoring overall network health trends. The tabular format enables detailed analysis and supports drill-down into specific band/RSRP combinations. This endpoint is critical for Ookla reporting modules that display comparative analysis and performance trends, supporting network monitoring and optimization workflows.",
      "query": "SELECT * FROM minds.ooklasectordaily WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET weeklyregionalspeedandcoverage/",
      "description": "Part of the Ookla reporting API (OOKLA_API_URL). This endpoint provides geographic analysis of network performance, showing how speed and coverage vary across different regions or states. The endpoint requires no parameters (or may accept week/year parameters) and returns regional performance data including state or region identifiers, frequency band information, average RSRP (signal strength) per region, and average download speeds per region. Geographic variation analysis is critical for network planning, as coverage and performance naturally vary based on terrain, population density, infrastructure deployment, and regional network maturity. Understanding regional differences enables network engineers to identify regions requiring additional coverage or capacity investments, prioritize optimization efforts based on regional performance gaps, assess the effectiveness of regional network improvements, and support strategic network expansion planning. The data helps explain performance differences to stakeholders, supports budget allocation decisions for network improvements, and enables comparison of network quality across different markets or service areas. This endpoint is essential for Ookla reporting modules that display geographic performance analysis, supporting network planning, optimization prioritization, and strategic decision-making.",
      "query": "SELECT * FROM minds.ooklasectordaily WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET filteringvalues_overall/",
      "description": "Part of the THD report API (THD_REPORT_API_URL). Returns the available global filter values for the THD Overall module (dropdown population).",
      "query": "SELECT * FROM `minds`.`thd` WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET filteringvalues_coverage_congestion/",
      "description": "Part of the THD report API (THD_REPORT_API_URL). Returns the available global filter values for the THD Coverage & Congestion module (dropdown population).",
      "query": "SELECT * FROM `minds`.`thd` WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET topcomplaintsite_overall/",
      "description": "Part of the THD report API (THD_REPORT_API_URL). The portal sends the same filter set as other overall endpoints. The server returns the list of top complaint sites for the overall view. Used in the THD reporting overall module to show which sites have the most complaints.",
      "query": "SELECT * FROM `minds`.`thd` WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
    {
      "endpoint": "GET complainttyperootcause_overall/",
      "description": "Part of the THD report API (THD_REPORT_API_URL). The portal sends the overall filters. The server returns complaint type and root cause breakdown. Used in the THD reporting overall module to analyse what types of complaints and root causes dominate.",
      "query": "SELECT * FROM `minds`.`thd` WHERE 1=1 LIMIT :limit OFFSET :offset"
    },
